{"file_path":"src/address.js","content":"/**
 * Cell address utilities: parsing an address token, converting between
 * column letters and numbers, and comparing addresses.
 */

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colToNum(colStr) {
  let n = 0
  for (const ch of colStr) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const r = (n - 1) % 26
    s = String.fromCharCode(65 + r) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse a raw token as a cell address. Returns null when the token does not
 * meet the address definition: one or two letters, one to three digits, and
 * a row of at least 1. Returns { col, row, colNum, key } otherwise, where
 * key is the canonical upper-cased "COLROW" string.
 */
export function parseAddressToken(token) {
  const m = ADDR_RE.exec(token)
  if (!m) return null
  const col = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const colNum = colToNum(col)
  return { col, row, colNum, key: col + row }
}

export function compareAddr(a, b) {
  if (a.colNum !== b.colNum) return a.colNum - b.colNum
  return a.row - b.row
}
"}

