{"file_path":"src/sheet.js","content":"/**
 * Parse a sheet given as raw text into a Map from canonical address key to
 * a cell record { col, row, colNum, content }.
 */

import { parseAddressToken } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]

    let j = 0
    while (j < line.length && (line[j] === ' ' || line[j] === '\t')) j++
    const rest = line.slice(j)
    if (rest.length === 0 || rest[0] === '#') continue

    let k = 0
    while (k < rest.length && rest[k] !== ' ' && rest[k] !== '\t') k++
    const addrToken = rest.slice(0, k)

    let m = k
    while (m < rest.length && (rest[m] === ' ' || rest[m] === '\t')) m++
    const content = rest.slice(m)

    const addr = parseAddressToken(addrToken)
    if (!addr) throw new SheetError(lineNo, `invalid cell address ${addrToken}`)
    if (cells.has(addr.key)) throw new SheetError(lineNo, `cell ${addr.key} is declared twice`)

    cells.set(addr.key, { col: addr.col, row: addr.row, colNum: addr.colNum, content })
  }

  return cells
}
"}

