{"file_path":"src/lexer.js","content":"/**
 * Tokenize a formula body (the text after the leading '=') into a token
 * stream for the parser. Spaces and tabs separate tokens and are otherwise
 * ignored.
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '^*/+-=<>(),:'

export function tokenize(s) {
  const tokens = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i))
      tokens.push({ type: 'NUM', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(s.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    let matched = null
    for (const op of TWO_CHAR_OPS) {
      if (s.startsWith(op, i)) {
        matched = op
        break
      }
    }
    if (!matched && ONE_CHAR_OPS.includes(c)) matched = c
    if (!matched) throw new LexError(`unexpected character ${c}`)
    tokens.push({ type: matched, value: matched })
    i += matched.length
  }
  tokens.push({ type: 'EOF', value: '' })
  return tokens
}
"}

{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for a formula's token stream, producing an AST.
 * Throws ParseError on anything the grammar does not accept.
 *
 * Precedence, loosest to tightest: comparisons, +/-, * //, ^, leading sign.
 * Comparisons, +/-, and * // are left-associative; ^ is right-associative;
 * a leading sign binds tighter than ^.
 *
 * A range (WORD ':' WORD) is only accepted directly as a function argument.
 */

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

export class ParseError extends Error {}

export function parseFormula(tokens) {
  let pos = 0
  const peek = () => tokens[pos]
  const next = () => tokens[pos++]
  const expect = (type) => {
    if (peek().type !== type) throw new ParseError(`expected ${type}`)
    return next()
  }

  function parseComparison() {
    let left = parseAdd()
    while (COMPARE_OPS.has(peek().type)) {
      const op = next().type
      const right = parseAdd()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  function parseAdd() {
    let left = parseMul()
    while (peek().type === '+' || peek().type === '-') {
      const op = next().type
      const right = parseMul()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  function parseMul() {
    let left = parsePow()
    while (peek().type === '*' || peek().type === '/') {
      const op = next().type
      const right = parsePow()
      left = { type: 'Bin', op, left, right }
    }
    return left
  }

  function parsePow() {
    const left = parseUnary()
    if (peek().type === '^') {
      next()
      const right = parsePow()
      return { type: 'Bin', op: '^', left, right }
    }
    return left
  }

  function parseUnary() {
    if (peek().type === '+' || peek().type === '-') {
      const op = next().type
      const operand = parseUnary()
      return { type: 'Unary', op, operand }
    }
    return parseAtom()
  }

  function parseAtom() {
    const t = peek()
    if (t.type === 'NUM') {
      next()
      return { type: 'Num', value: parseFloat(t.value) }
    }
    if (t.type === '(') {
      next()
      const e = parseComparison()
      expect(')')
      return e
    }
    if (t.type === 'WORD') {
      next()
      const upper = t.value.toUpperCase()
      if (peek().type === '(') {
        next()
        const args = []
        if (peek().type !== ')') {
          args.push(parseArg())
          while (peek().type === ',') {
            next()
            args.push(parseArg())
          }
        }
        expect(')')
        return { type: 'Call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      return { type: 'Address', token: upper }
    }
    throw new ParseError('unexpected token')
  }

  function parseArg() {
    if (peek().type === 'WORD') {
      const save = pos
      const w1 = next()
      if (peek().type === ':') {
        next()
        if (peek().type !== 'WORD') throw new ParseError('expected address after :')
        const w2 = next()
        return { type: 'Range', from: w1.value.toUpperCase(), to: w2.value.toUpperCase() }
      }
      pos = save
    }
    return parseComparison()
  }

  const result = parseComparison()
  expect('EOF')
  return result
}
"}

{"file_path":"src/values.js","content":"/**
 * Value representation and shared operations: literal parsing, numeric
 * coercion for arithmetic, and cross-kind comparison.
 */

export const numVal = (v) => ({ t: 'num', v })
export const textVal = (v) => ({ t: 'text', v })
export const boolVal = (v) => ({ t: 'bool', v })
export const errVal = (v) => ({ t: 'err', v })

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

export function parseLiteral(content) {
  if (content === '') return numVal(0)
  if (NUMBER_RE.test(content)) return numVal(parseFloat(content))
  if (ERROR_TOKENS.has(content)) return errVal(content)
  return textVal(content)
}

/** Convert a value to a number for arithmetic. Returns null when the value
 * is text (the caller should produce #VALUE!). Errors must be filtered out
 * by the caller before calling this. */
export function toNumberCoerce(v) {
  if (v.t === 'num') return v.v
  if (v.t === 'bool') return v.v ? 1 : 0
  if (v.t === 'text') return null
  return null
}

function typeRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2 // bool
}

export function compareValues(l, r) {
  const rl = typeRank(l)
  const rr = typeRank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.t === 'num') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  if (l.t === 'text') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  const lv = l.v ? 1 : 0
  const rv = r.v ? 1 : 0
  return lv - rv
}
"}

{"file_path":"src/format.js","content":"/**
 * Formatting values for the `values` mode's output.
 */

function roundToSigFigs(n, sig) {
  if (!Number.isFinite(n) || n === 0) return n
  return parseFloat(n.toPrecision(sig))
}

export function formatNumber(n) {
  return String(roundToSigFigs(n, 10))
}

export function formatValue(v) {
  switch (v.t) {
    case 'num':
      return formatNumber(v.v)
    case 'text':
      return v.v
    case 'bool':
      return v.v ? 'TRUE' : 'FALSE'
    case 'err':
      return v.v
    default:
      throw new Error('unknown value kind')
  }
}
"}

