{"file_path":"src/evaluator.js","content":"/**
 * Evaluates a sheet's cells, with formula parsing, memoization, and cycle
 * detection.
 */

import { tokenize, LexError } from './lexer.js'
import { parseFormula, ParseError } from './parser.js'
import { parseAddressToken, numToCol } from './address.js'
import { numVal, boolVal, errVal, parseLiteral, toNumberCoerce, compareValues } from './values.js'

const AGGREGATE_NAMES = new Set(['SUM', 'MIN', 'MAX', 'AVG', 'COUNT'])

export function makeEvaluator(cells) {
  const parsedCache = new Map()
  const valueCache = new Map()
  const visiting = new Set()

  function parseCellContent(entry) {
    const content = entry.content
    if (content.startsWith('=')) {
      try {
        const tokens = tokenize(content.slice(1))
        const ast = parseFormula(tokens)
        return { kind: 'formula', ast }
      } catch (e) {
        if (e instanceof LexError || e instanceof ParseError) return { kind: 'error', value: errVal('#ERR!') }
        throw e
      }
    }
    return { kind: 'literal', value: parseLiteral(content) }
  }

  function getParsed(key) {
    if (parsedCache.has(key)) return parsedCache.get(key)
    const p = parseCellContent(cells.get(key))
    parsedCache.set(key, p)
    return p
  }

  function getCellValue(key) {
    if (valueCache.has(key)) return valueCache.get(key)
    if (!cells.has(key)) {
      const v = numVal(0)
      valueCache.set(key, v)
      return v
    }
    if (visiting.has(key)) return errVal('#CYCLE!')

    const p = getParsed(key)
    if (p.kind === 'literal' || p.kind === 'error') {
      valueCache.set(key, p.value)
      return p.value
    }

    visiting.add(key)
    const v = evalNode(p.ast)
    visiting.delete(key)
    valueCache.set(key, v)
    return v
  }

  function expandRange(node) {
    const a = parseAddressToken(node.from)
    const b = parseAddressToken(node.to)
    if (!a || !b) return [null]
    const minCol = Math.min(a.colNum, b.colNum)
    const maxCol = Math.max(a.colNum, b.colNum)
    const minRow = Math.min(a.row, b.row)
    const maxRow = Math.max(a.row, b.row)
    const keys = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) keys.push(numToCol(c) + r)
    }
    return keys
  }

  function evalArgSingle(node) {
    if (node.type === 'Range') {
      const keys = expandRange(node)
      const first = keys[0]
      return first === null ? errVal('#REF!') : getCellValue(first)
    }
    return evalNode(node)
  }

  function flattenArgs(argNodes) {
    const out = []
    for (const node of argNodes) {
      if (node.type === 'Range') {
        for (const key of expandRange(node)) out.push(key === null ? errVal('#REF!') : getCellValue(key))
      } else {
        out.push(evalNode(node))
      }
    }
    return out
  }

  function applyUnary(op, v) {
    if (v.t === 'err') return v
    const n = toNumberCoerce(v)
    if (n === null) return errVal('#VALUE!')
    const res = op === '-' ? -n : n
    if (!Number.isFinite(res)) return errVal('#DIV/0!')
    return numVal(res)
  }

  function applyBin(op, l, r) {
    if (op === '=' || op === '<>' || op === '<' || op === '<=' || op === '>' || op === '>=') {
      if (l.t === 'err') return l
      if (r.t === 'err') return r
      const cmp = compareValues(l, r)
      let res
      if (op === '=') res = cmp === 0
      else if (op === '<>') res = cmp !== 0
      else if (op === '<') res = cmp < 0
      else if (op === '<=') res = cmp <= 0
      else if (op === '>') res = cmp > 0
      else res = cmp >= 0
      return boolVal(res)
    }
    if (l.t === 'err') return l
    if (r.t === 'err') return r
    const ln = toNumberCoerce(l)
    if (ln === null) return errVal('#VALUE!')
    const rn = toNumberCoerce(r)
    if (rn === null) return errVal('#VALUE!')
    let res
    if (op === '+') res = ln + rn
    else if (op === '-') res = ln - rn
    else if (op === '*') res = ln * rn
    else if (op === '/') {
      if (rn === 0) return errVal('#DIV/0!')
      res = ln / rn
    } else res = Math.pow(ln, rn) // '^'
    if (!Number.isFinite(res)) return errVal('#DIV/0!')
    return numVal(res)
  }

  function evalCall(node) {
    const name = node.name
    const argNodes = node.args

    if (AGGREGATE_NAMES.has(name)) {
      if (argNodes.length < 1) return errVal('#ERR!')
      const flat = flattenArgs(argNodes)
      for (const v of flat) if (v.t === 'err') return v
      if (name === 'COUNT') return numVal(flat.filter((v) => v.t === 'num').length)
      const nums = []
      for (const v of flat) {
        const n = toNumberCoerce(v)
        if (n === null) return errVal('#VALUE!')
        nums.push(n)
      }
      if (name === 'SUM') {
        const res = nums.reduce((a, b) => a + b, 0)
        return Number.isFinite(res) ? numVal(res) : errVal('#DIV/0!')
      }
      if (name === 'MIN') return numVal(Math.min(...nums))
      if (name === 'MAX') return numVal(Math.max(...nums))
      // AVG
      const res = nums.reduce((a, b) => a + b, 0) / nums.length
      return Number.isFinite(res) ? numVal(res) : errVal('#DIV/0!')
    }

    if (name === 'ABS') {
      if (argNodes.length !== 1) return errVal('#ERR!')
      const v = evalArgSingle(argNodes[0])
      if (v.t === 'err') return v
      const n = toNumberCoerce(v)
      if (n === null) return errVal('#VALUE!')
      return numVal(Math.abs(n))
    }

    if (name === 'IF') {
      if (argNodes.length !== 3) return errVal('#ERR!')
      const cond = evalArgSingle(argNodes[0])
      if (cond.t === 'err') return cond
      let truthy
      if (cond.t === 'bool') truthy = cond.v
      else if (cond.t === 'num') truthy = cond.v !== 0
      else return errVal('#VALUE!')
      return evalArgSingle(truthy ? argNodes[1] : argNodes[2])
    }

    return errVal('#NAME?')
  }

  function evalNode(node) {
    switch (node.type) {
      case 'Num':
        return numVal(node.value)
      case 'Bool':
        return boolVal(node.value)
      case 'Address': {
        const addr = parseAddressToken(node.token)
        if (!addr) return errVal('#REF!')
        return getCellValue(addr.key)
      }
      case 'Unary':
        return applyUnary(node.op, evalNode(node.operand))
      case 'Bin':
        return applyBin(node.op, evalNode(node.left), evalNode(node.right))
      case 'Call':
        return evalCall(node)
      default:
        throw new Error('unknown node type')
    }
  }

  return { getCellValue }
