{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { makeEvaluator } from './evaluator.js'
import { parseAddressToken } from './address.js'
import { formatValue } from './format.js'
import { collectFormulaDeps } from './deps.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function byAddress(cells) {
  return (a, b) => {
    const ca = cells.get(a)
    const cb = cells.get(b)
    if (ca.colNum !== cb.colNum) return ca.colNum - cb.colNum
    return ca.row - cb.row
  }
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  const input = await readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
      process.exitCode = 2
      return
    }
    throw e
  }

  const sortedKeys = [...cells.keys()].sort(byAddress(cells))

  let out = ''
  if (mode === 'values') {
    const evaluator = makeEvaluator(cells)
    for (const key of sortedKeys) {
      out += `${key}=${formatValue(evaluator.getCellValue(key))}\n`
    }
  } else {
    for (const key of sortedKeys) {
      const depKeys = collectFormulaDeps(cells.get(key).content)
      depKeys.sort((a, b) => {
        const pa = parseAddressToken(a)
        const pb = parseAddressToken(b)
        if (pa.colNum !== pb.colNum) return pa.colNum - pb.colNum
        return pa.row - pb.row
      })
      out += depKeys.length ? `${key}: ${depKeys.join(' ')}\n` : `${key}:\n`
    }
  }

  process.exitCode = 0
  process.stdout.write(out)
}

main().catch((e) => {
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
})
"}

